}
out;

ruleContent.content:
@js:
var u0 = String(baseUrl || '');
var out = '';
var mb = /[?&]b=(\d+)/.exec(u0);
var mp = /[?&]part=(\d+)/.exec(u0);
if (mb) {
  var me2 = /[?&]e=(\d+)/.exec(u0);
  var b0 = u0.replace(/[?&](b|e)=[^&]*/g, '').replace(/\?$/, '');
  var sA = parseInt(mb[1], 10) - 4; if (sA < 0) { sA = 0; }
  var rng = 'bytes=' + sA + '-' + (me2 ? String(me2[1]) : '');
  try { out = String(java.ajax(b0 + ',{"headers":{"Range":"' + rng + '"}}')); } catch (e) { out = ''; }
} else if (mp) {
  var mn = /[?&]n=(\d+)/.exec(u0);
  var mc = /[?&]ch=(\d+)/.exec(u0);
  var idx = parseInt(mp[1], 10);
  var tot = mn ? parseInt(mn[1], 10) : 1;
  var ch = mc ? parseInt(mc[1], 10) : 1000000;
  var b1 = u0.replace(/[?&](part|n|ch)=[^&]*/g, '').replace(/\?$/, '');
  var a1 = idx * ch;
  var e1 = (idx + 1 >= tot) ? '' : String((idx + 1) * ch - 1);
  try { out = String(java.ajax(b1 + ',{"headers":{"Range":"bytes=' + a1 + '-' + e1 + '"}}')); } catch (e) { out = ''; }
}
if (!out) { out = String(result || ''); }
var s = out;
if (s.substr(0, 2) === 'PK' && s.charCodeAt(2) === 3) {
  s = '【压缩包】本站在该书上架较早，只提供 ZIP 压缩包，阅读器无法解压。请复制本章链接用浏览器下载后用「本地导入」：' + u0;
} else {
  s = s.replace(/<br\s*\/?>/ig, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&raquo;/g, '').replace(/&amp;/g, '&').replace(/\ufeff/g, '');
  s = s.replace(/推荐一个小说下载必备网址[^\n]*/g, '').replace(/每天更新，喜欢的去看看。[^\n]*/g, '');
  s = s.replace(/\r/g, '').replace(/\u3000\u3000/g, '\n').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n');
  s = s.replace(/^[\s\n\uFFFD]+/, '').replace(/[\s\n\uFFFD]+$/, '');
}
result = s;
s

ruleToc.chapterList:
@js:
var h = String(result || '');
var re = /<a[^>]*href="(https?:\/\/[^"]+\.txt)"[^>]*>([^<]*)<\/a>/gi, m, u = '';
while ((m = re.exec(h))) { if (String(m[2]).indexOf('在线阅读') < 0) { u = m[1]; break; } }
if (!u) { var r2 = /<a[^>]*href="(https?:\/\/[^"]+\.txt)"/i.exec(h); if (r2) { u = r2[1]; } }
var sp = /小说大小[\s\S]{0,60}?([0-9]+(?:\.[0-9]+)?)\s*(M|K|G)B/i.exec(h);
var sz = 0;
if (sp) { var un = String(sp[2]).toUpperCase(); sz = parseFloat(sp[1]) * (un === 'M' ? 1048576 : (un === 'K' ? 1024 : 1073741824)); }
if (sz > 0) { sz = Math.floor(sz * 0.97); }
var arr = [];
if (u && /\.txt/i.test(u)) {
  if (!(sz > 0)) { sz = 4 * 1048576; }
  var CH = 1000000;
  var n = Math.ceil(sz / CH);
  if (n < 1) { n = 1; }
  if (n > 60) { CH = Math.ceil(sz / 60); n = Math.ceil(sz / CH); }
  var heads = [];
  var ok = true;
  for (var i = 0; i < n; i++) {
    var a = i * CH;
    var b = (i + 1 >= n) ? '' : String((i + 1) * CH - 1);
    var t = '';
    try { t = String(java.ajax(u + ',{"headers":{"Range":"bytes=' + a + '-' + b + '"}}')); } catch (e) { t = ''; }
    if (!t) { ok = false; break; }
    var hr = /第[\d零一二三四五六七八九十百千万]{1,8}[章回节][^\n\r]{0,30}/g, hm;
    var pos = 0, bytes = 0;
    while ((hm = hr.exec(t))) {
      for (; pos < hm.index; pos++) {
        var c = t.charCodeAt(pos);
        bytes += (c < 128) ? 1 : ((c < 2048) ? 2 : ((c >= 55296 && c <= 56319) ? 4 : 3));
      }
      heads.push({ 'name': String(hm[0]).replace(/[\s\u3000]+/g, ' ').trim(), 'off': a + bytes });
    }
  }
  if (ok && heads.length >= 5) {
    for (var k = 0; k < heads.length; k++) {
      var e0 = (k + 1 < heads.length) ? String(heads[k + 1].off - 1) : '';
      arr.push({ 'ChapterName': heads[k].name, 'ChapterUrl': u + '?b=' + heads[k].off + '&e=' + e0 });
    }
  }
  if (arr.length === 0) {
    for (var j = 0; j < n; j++) {
      arr.push({ 'ChapterName': '第' + (j + 1) + '部分/共' + n + '部分', 'ChapterUrl': u + '?part=' + j + '&n=' + n + '&ch=' + CH });
    }
  }
} else if (u) {
  arr.push({ 'ChapterName': '压缩包(ZIP)', 'ChapterUrl': u });
}
if (arr.length === 0) { arr.push({ 'ChapterName': '全文', 'ChapterUrl': '' }); }
arr
